def copy_saved_captions(apps, schema_editor):
    """ย้ายคำอธิบายที่เคยบันทึกไว้ใน project.config มาเป็นประวัติ"""
    VideoProject = apps.get_model("videogen", "VideoProject")
    PostCaption = apps.get_model("videogen", "PostCaption")
    for p in VideoProject.objects.all():
        cfg = p.config or {}
        found = dict(cfg.get("captions") or {})
        old = cfg.get("caption")
        if old and old.get("description"):
            found.setdefault(old.get("lang", "th"), old)
        for lang, c in found.items():
            if not isinstance(c, dict) or not c.get("description"):
                continue
            PostCaption.objects.create(
                user_id=p.user_id, project=p, lang=lang if lang in ("th", "en", "both") else "th", source="ai",
                title=str(c.get("title") or "")[:200], description=str(c.get("description") or ""),
                hashtags=[str(t) for t in (c.get("hashtags") or [])], idea=p.idea or "")


